ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/'tools'))
from edit_chapter import load,save,transform
paragraphs={
'Пусть для evaluation внешняя training часть':'''Пусть внешняя обучающая часть содержит строки 1–8, а проверочная — 9–10. Если заранее построить OOF по всем десяти строкам с разбиением на чётные и нечётные, строка 1 использует среднее чётных строк, куда входит метка строки 10 из внешней проверки. Собственная метка строки 1 исключена, но внешняя проверка уже влияет на обучение. При переключении y₁₀ с 0 на 1 среднее меняется с 1/5 до 2/5, а z₁ — с 2/15 до 4/15.''',
'Правильный порядок: выбрать внешний train':'''Правильный порядок: выделить внешнюю обучающую часть; внутри неё заново получить OOF-признаки; обучить следующую модель; построить таблицу для применения по всей внешней обучающей части; только затем преобразовать внешнюю проверку. При подборе α, порогов объединения категорий или сложности модели процедуру повторяют внутри разрешённого протокола. Финальный тест не используют как ещё одну проверку для выбора кодировки.''',
'При K folds OOF statistics':r'''При K folds справочные данные для OOF-статистик обычно составляют примерно $(K-1)/K$ обучающей выборки, а таблица для новых объектов использует её целиком. У редких категорий различаются количества наблюдений, дисперсия и число резервных значений. Больший K уменьшает разницу объёмов, но повышает вычислительную стоимость и перекрытие частей; бесконечного выигрыша не обещает. Усреднение нескольких моделей с таблицами отдельных folds — другой алгоритм с другими обучающими наборами; его сравнивают отдельно от полного переобучения.''',
'Повторный cross-fitting с несколькими seeds':'''Повторное перекрёстное вычисление с несколькими начальными состояниями генератора может уменьшить чувствительность к одному разбиению. Однако внешняя проверка остаётся отдельной; усреднение OOF-значений само по себе не доказывает качество, а повторные разбиения не создают независимых наборов данных. В начале временного ряда доступной истории может не быть: используют заранее доступное среднее, период накопления или исключают начальные строки из обучения, явно обозначив оцениваемую популяцию. Будущие метки нельзя использовать ради заполнения ячеек.''',
'Для внешнего train $T$ строим':r'''Для внешней обучающей части $T$ строим внутренние folds $T_1,\ldots,T_K$. Каждая строка $i\in T_k$ кодируется таблицей, вычисленной по $T\setminus T_k$; на этих OOF-признаках обучают следующую модель. Для внешней проверочной части $V$ отдельную таблицу строят по всему $T$ и применяют без меток $V$:''',
'Нельзя сначала получить OOF feature':'''Нельзя сначала получить OOF-признак по всей выборке, а затем выполнить внешнюю перекрёстную проверку: метки внешней проверки уже могли попасть в признаки внешнего обучения. На каждой внешней итерации процедуру подготовки повторяют заново.''',
'Group/time constraints действуют':'''Ограничения по группам и времени действуют также на внутреннем разбиении. Случайный внутренний KFold не создаёт причинно доступные признаки для исторического прогноза. В scikit-learn `TargetEncoder.fit_transform` и `fit(...).transform(...)` на обучающей части различаются из-за перекрёстного вычисления; доступные варианты разбиения зависят от версии. См. [документацию TargetEncoder](https://scikit-learn.org/stable/modules/generated/sklearn.preprocessing.TargetEncoder.html). Другой кодировщик с похожим названием не обязательно выполняет этот шаг автоматически.''',
'LOO исключает собственный label':'''Метод исключения одной строки (LOO) удаляет собственную метку из суммы категории:''',
'Здесь показан и prior без собственной строки':'''Здесь общее среднее тоже рассчитано без собственной строки. Для категории из двух объектов без сглаживания признак первого равен метке второго. Это исключает прямое включение собственного ответа, но оставляет сильную зависимость примеров и различие между обучением и применением. LOO не становится автоматически безопаснее корректного перекрёстного вычисления.''',
'Ordered statistics CatBoost используют':'''В упорядоченных статистиках CatBoost для каждой строки используются предшествующие ей примеры некоторой перестановки и априорное значение. Этот способ отличается от полного среднего и предназначен для борьбы с определённым сдвигом, связанным с утечкой целевой информации. Случайная перестановка не является хронологической историей: доступность меток во временной задаче контролируют отдельно. Упорядоченные статистики и ordered boosting — связанные, но разные компоненты алгоритма. [Статья CatBoost](https://arxiv.org/abs/1706.09516).''',
'В учебном варианте ordered statistics':'''В учебном варианте с μ=0.5, α=2 и последовательностью A:1, A:0, B:1, A:1 значения перед очередным обновлением равны 0.5, 2/3, 0.5, 0.5. Сначала признак вычисляют по предшествующим строкам, затем добавляют текущую метку. Обратный порядок вновь включает ответ. Пример показывает принцип префикса, а не воспроизводит все разновидности статистик CatBoost.''',
'Случайная permutation обеспечивает':'''Случайная перестановка задаёт алгоритмический порядок внутри обучающего набора, но не устанавливает фактическую временную доступность. Ordered boosting дополнительно учитывает зависимости при последовательном построении остатков бустинга; его нельзя свести к одному заранее вычисленному столбцу целевой статистики. Механизм компонентов описан в [работе CatBoost](https://arxiv.org/abs/1706.09516).''',
'Для собственного pipeline сохраняют':'''Для собственного конвейера сохраняют схему полей, нормализацию категорий, правило разбиения и справочной выборки, суммы и количества, априорное значение, сглаживание, порядок классов, резервное значение и временную границу данных. При применении метки не обновляют, если явно не задан онлайн-протокол. После сохранения и загрузки проверяют известные, редкие, отсутствующие и новые значения: одного совпадения формы массива недостаточно.''',
'В [документации TargetEncoder]':'''Документация [TargetEncoder](https://scikit-learn.org/stable/modules/generated/sklearn.preprocessing.TargetEncoder.html) различает обучающий `fit_transform` с перекрёстным вычислением и `transform` с сохранённой таблицей. Поддержка передаваемых разбиений зависит от установленной версии. Временное разбиение, которое не покрывает каждую обучающую строку ровно один раз, может не соответствовать контракту API; тогда нужен явный построитель признаков по доступной истории.''',
'**Самопроверка:** singleton':'''**Самопроверка:** сглаживание не скрывает метку одиночной категории; общее среднее тоже может содержать собственную метку; OOF до внешнего разбиения недостаточно; групповые и временные ограничения действуют на обоих уровнях; полная таблица и OOF-матрица — разные артефакты.''',
'При выбранном positive class определим':'''Для выбранного положительного класса определим вес свидетельства (weight of evidence, WoE):''',
'WoE отличается от posterior log-odds':'''WoE отличается от апостериорного логарифма шансов на логарифм априорных шансов; знак меняется при перестановке положительного и отрицательного классов. Нулевые счётчики дают бесконечность без сглаживания. Разбиение на интервалы, сглаживание и таблицу по меткам обучают только на разрешённой части; обучающим строкам следующей модели также нужен корректный протокол. WoE не устраняет утечку автоматически.''',
'Для L классов зададим prior probabilities':r'''Для $L$ классов зададим априорные доли $\pi_\ell$, сумма которых равна 1. Тогда:''',
'При counts (2,1,0), prior':'''При количествах (2,1,0), априорных долях (0.2,0.3,0.5) и α=2 получаем (0.48,0.32,0.20); сумма равна 1. Отсутствие третьего класса среди трёх наблюдений не означает, что его вероятность доказанно равна нулю. Если в обучающей части отдельного fold отсутствует один из классов, сохраняют объявленный набор столбцов и предусмотренные априорные доли, иначе при объединении можно смешать значения разных классов.''',
'Sample weights меняют':r'''Веса строк меняют оцениваемую популяцию. Взвешенная статистика использует $s_c=\sum w_i y_i$, $n_c=\sum w_i$ и согласованное взвешенное среднее. Умножение всех весов на 10 меняет относительную силу фиксированного α: её единица — выбранная масса наблюдений. Для весов 1 и 9 эффективный размер по формуле $(\sum w)^2/\sum w^2$ равен $100/82\approx1.22$, а не десяти независимым наблюдениям. Это показатель концентрации весов при соответствующих предположениях, а не универсальная замена числа наблюдений во всех моделях.''',
'Пусть всего 40 positives':'''Пусть всего 40 положительных и 60 отрицательных меток; у категории c — 12 положительных и 6 отрицательных. Тогда WoE=log((12/40)/(6/60))=log 3≈1.0986. Условная вероятность положительного класса равна 12/18=2/3, логарифм условных шансов — log 2≈0.6931. Разница объясняется априорным логарифмом шансов log(40/60)≈−0.4055: log 3+log(2/3)=log 2.''',
'При smoothing нужно объявить':r'''При сглаживании нужно объявить, какое распределение меняется. Для конечного словаря из трёх категорий добавление единицы к каждому счётчику категории внутри класса даёт вероятности 13/43 и 7/63 для c; сглаженный WoE равен log(117/43)≈1.0010. Это отличается от добавления единицы к двум исходам внутри c и вычисления log(13/7). Первое сглаживает $P(C\mid Y)$, второе — условные шансы исхода; нельзя смешивать их нормировки и ссылаться на точное равенство Байеса для одного общего распределения.''',
'Supervised binning числового field':'''Разбиение числового поля на интервалы с использованием меток тоже обучается: границы, монотонные ограничения и объединение редких интервалов выбирают только на разрешённой обучающей части. Бесконечность из-за нулевого счётчика говорит об ограниченности оценки, а не о доказанном бесконечном отношении рисков. Ограничение значений задаёт дополнительный параметр, а последующая логистическая регрессия не устраняет утечку из признаков.''',
}
def operation(text):
 for prefix,replacement in paragraphs.items():
  start=text.find(prefix)
  if start<0:raise ValueError('Missing paragraph: '+prefix)
  ends=[i for i in (text.find('\n\n',start),text.find('\n<!-- EDIT:',start),text.find('\n<!-- /EDIT:',start)) if i>=0]
  if not ends:raise ValueError('Missing boundary: '+prefix)
  end=min(ends);text=text[:start]+replacement+text[end:]
 return text
c=load();transform('01-data-features/02-features/feat-target.md',operation,
 'Пакет 03: редактура вложенной оценки, упорядоченных статистик и WoE с сохранением численных примеров; содержательная приёмка ожидается.',c);save(c)
print('Target protocol and WoE edited; review stays open.')
